
-- Create a system/seed user in auth.users for tournament seeding purposes
-- Then insert tournaments referencing that user

-- First, create a known UUID for the seed organizer
DO $$
DECLARE
  seed_user_id uuid := 'a0000000-0000-0000-0000-000000000001';
BEGIN
  -- Insert into auth.users if not exists
  INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, created_at, updated_at, confirmation_token, raw_app_meta_data, raw_user_meta_data)
  VALUES (
    seed_user_id,
    '00000000-0000-0000-0000-000000000000',
    'authenticated',
    'authenticated',
    'organizador@torneobase.app',
    crypt('SeedPassword123!', gen_salt('bf')),
    now(),
    now(),
    now(),
    '',
    '{"provider":"email","providers":["email"]}',
    '{"display_name":"TorneoBase Organizador","full_name":"TorneoBase Organizador"}'
  )
  ON CONFLICT (id) DO NOTHING;
END $$;

